import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../auth/presentation/auth_providers.dart';class ProfileScreen extends ConsumerWidget{const ProfileScreen({super.key});@override Widget build(BuildContext c,WidgetRef r){final u=r.watch(authSessionProvider)?.user;return Scaffold(appBar:AppBar(title:const Text('Profile')),body:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(u?.name??'Guest',style:Theme.of(c).textTheme.headlineSmall),Text(u?.phone??''),Text(u?.email??''),const Spacer(),FilledButton(onPressed:(){r.read(authSessionProvider.notifier).logout();},child:const Text('Logout'))])));}}
